<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
require_once __DIR__ . '/admin-ui.php';
$user = require_admin(); $db = blog_db();
$counts = ['total'=>(int)$db->query('SELECT COUNT(*) FROM posts')->fetchColumn(),'draft'=>(int)$db->query("SELECT COUNT(*) FROM posts WHERE status='draft'")->fetchColumn(),'published'=>(int)$db->query("SELECT COUNT(*) FROM posts WHERE status='published'")->fetchColumn(),'archived'=>(int)$db->query("SELECT COUNT(*) FROM posts WHERE status='archived'")->fetchColumn(),'categories'=>(int)$db->query('SELECT COUNT(*) FROM categories')->fetchColumn()];
$activity=$db->query('SELECT a.*,u.name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 6')->fetchAll(); admin_layout_start('Dashboard','dashboard',$user);
?><div class="bar"><div><h1>Blog dashboard</h1><p>Signed in as <?=htmlspecialchars($user['name'])?> (<?=htmlspecialchars($user['role'])?>)</p></div><a class="btn" href="/admin/post-edit.php">Add New Post</a></div><section class="grid"><article class="card"><h2><?=$counts['total']?> posts</h2><p><?=$counts['draft']?> draft · <?=$counts['published']?> published · <?=$counts['archived']?> archived</p><a href="/admin/posts.php">All Posts</a></article><article class="card"><h2><?=$counts['categories']?> categories</h2><p>Organize devotional travel content for SEO and visitors.</p><a href="/admin/category-edit.php">Add Category</a> · <a href="/admin/categories.php">All Categories</a></article><article class="card"><h2>Quick links</h2><p><a href="/admin/post-edit.php">Add New Post</a><br><a href="/admin/posts.php">All Posts</a><br><a href="/admin/category-edit.php">Add Category</a><br><a href="/admin/categories.php">All Categories</a></p></article></section><section class="card" style="margin-top:22px"><h2>Recent activity</h2><?php if($activity):?><table><thead><tr><th>When</th><th>User</th><th>Action</th><th>Item</th></tr></thead><tbody><?php foreach($activity as$a):?><tr><td><?=htmlspecialchars($a['created_at'])?></td><td><?=htmlspecialchars($a['name']??'System')?></td><td><?=htmlspecialchars($a['action'])?></td><td><?=htmlspecialchars($a['entity_type'])?> #<?=htmlspecialchars((string)$a['entity_id'])?></td></tr><?php endforeach?></tbody></table><?php else:?><p>No admin activity yet.</p><?php endif?></section><?php admin_layout_end();
